new='''/** Counts live comments (replies included); deleted ones are not counted. */
export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          livePredicate(comments.archivedAt, {}),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Live comments on one issue in id order, `limit` at a time, resuming after
 * `afterId`. Replies are included whether or not their parent is still live.
 * Walked by the search reindex, which has to reach every comment however long
 * the discussion is.
 */
export async function listLiveCommentsForIssue(
  orgId: OrgId,
  issueId: IssueId,
  afterId: CommentId | null,
  limit: number,
): Promise<readonly Comment[]> {
  const rows = getDb()
    .select()
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          livePredicate(comments.archivedAt, {}),
          afterId === null ? undefined : gt(comments.id, afterId),
        ),
      ),
    )
    .orderBy(asc(comments.id))
    .limit(limit)
    .all();

  return rows.map(toComment);
}

/** Ids of every comment on an issue, deleted ones included. */
export async function listCommentIdsForIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentId[]> {
  const rows = getDb()
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .all();
  return rows.map((row) => row.id as CommentId);
}
