import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});
afterAll(() => { detach(); cleanup(); });

async function q(t: any, text: string, kinds: any[] = []) {
  return searchService.search(t.actors.member, { orgId: t.org.id, q: text, kinds, limit: 100, cursor: null });
}

describe("scratch", () => {
  it("works end to end", async () => {
    const t = await createTenant("scr1");
    const o = await createTenant("scr2");
    const mk = async (tt: any, title: string) =>
      issueService.createIssue(tt.actors.member, issueInput(tt.org.id, tt.project.id, { title }));
    const cm = async (tt: any, issueId: any, body: string, parentId: any = null) =>
      commentService.createComment(tt.actors.member, { orgId: tt.org.id, issueId, body, parentId, mentionedUserIds: [] });

    const i1 = await mk(t, "alpha issue");
    const i2 = await mk(t, "beta issue");
    const oi = await mk(o, "alpha other");
    const c1 = await cm(t, i1.id, "zzcomment one");
    const r1 = await cm(t, i1.id, "zzreply one", c1.id);
    const c2 = await cm(t, i1.id, "zzcomment two");
    const oc = await cm(o, oi.id, "zzcomment other");
    const b1 = await cm(t, i2.id, "zzcomment beta");

    expect((await issueService.getIssue(t.actors.member, t.org.id, i1.id)).commentCount).toBe(3);
    await commentService.deleteComment(t.actors.member, { orgId: t.org.id, commentId: c1.id } as any);
    expect((await issueService.getIssue(t.actors.member, t.org.id, i1.id)).commentCount).toBe(2);
    expect((await q(t, "zzcomment one")).total).toBe(0);
    expect((await q(t, "zzreply one")).total).toBe(1);
    expect((await q(t, "alpha issue")).total).toBe(1);

    // rebuild twice: reply with deleted parent still indexed, deleted not
    await runSearchReindexJob(t.org.id);
    await runSearchReindexJob(t.org.id);
    expect((await q(t, "zzcomment one")).total).toBe(0);
    expect((await q(t, "zzreply one")).total).toBe(1);
    expect((await q(t, "zzcomment two")).total).toBe(1);
    expect((await q(t, "issue")).total).toBe(2);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(1 + 2 + 1 + 2 + 1 - 1 + 0);
    expect((await q(o, "zzcomment other")).total).toBe(1);

    await issueService.archiveIssue(t.actors.member, t.org.id, i1.id);
    expect((await q(t, "zz")).total).toBe(1);
    expect((await q(t, "alpha issue")).total).toBe(0);
    expect((await q(o, "zzcomment other")).total).toBe(1);
    await runSearchReindexJob(t.org.id);
    expect((await q(t, "zz")).total).toBe(1);
    expect((await q(t, "alpha issue")).total).toBe(0);
    expect((await q(o, "zz")).total).toBe(1);
    expect(oc.id).toBeTruthy(); expect(b1.id).toBeTruthy(); expect(r1.id).toBeTruthy(); expect(c2.id).toBeTruthy();
  });

  it("covers large backlogs", async () => {
    const t = await createTenant("scr3");
    const ids: any[] = [];
    for (let n = 0; n < 250; n += 1) {
      const issue = await issueRepo.insertIssue(
        { ...issueInput(t.org.id, t.project.id, { title: `bulk issue ${n}` }) } as any,
        t.userIds.member, n + 1);
      ids.push(issue.id);
    }
    for (let n = 0; n < 230; n += 1) {
      await commentRepo.insertComment(
        { orgId: t.org.id, issueId: ids[0], body: `bulk comment ${n}`, parentId: null, mentionedUserIds: [] } as any,
        t.userIds.member);
    }
    const res = await runSearchReindexJob(t.org.id);
    console.log(res);
    expect((await q(t, "bulk issue")).total).toBe(250);
    expect((await q(t, "bulk comment")).total).toBe(230);
    expect((await q(t, "bulk comment 0")).total).toBeGreaterThan(0);
    await runSearchReindexJob(t.org.id);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(1 + 250 + 230);
  });
});
